sysevent_in_email_action.script:
(function runAction(/*GlideRecord*/ current, /*GlideRecord*/ event, /*EmailWrapper*/ email, /*ScopedEmailLogger*/ logger, /*EmailClassifier*/ classifier) {

	// Create a new incident record
// Create a new incident based on the email content
// Create a new incident based on the email content
// Create a new incident
var gr = new GlideRecord('incident');
gr.initialize();
gr.description = email.body_text;
gr.short_description = email.subject;
gr.assignment_group = 'cf82445687e61e1036a740860cbb35f5';
var incidentSysId = gr.insert();

if (!incidentSysId) {
    gs.error("Incident creation failed.");
    return;
}
gs.log("Incident created successfully with sys_id: " + incidentSysId);

// Process attachments linked to the sys_email record
var attachmentGr = new GlideRecord('sys_attachment');
attachmentGr.addQuery('table_name', 'sys_email');
attachmentGr.addQuery('table_sys_id', email.sys_id);
attachmentGr.query();

if (attachmentGr.hasNext()) {
    while (attachmentGr.next()) {
        try {
            gs.log("Processing email attachment: " + attachmentGr.file_name);
            attachmentGr.copyToRecord('incident', incidentSysId);
            gs.log("Attachment copied successfully to incident: " + attachmentGr.file_name);
        } catch (e) {
            gs.error("Failed to copy attachment: " + attachmentGr.file_name + ". Error: " + e.message);
        }
    }
} else {
    gs.log("No attachments found on the email record.");
}




})(current, event, email, logger, classifier);
